// B · Explorar (design @lisanogueira). One terrain layer at a time, painted from repository data:
// altitude = LOLA 400 m grid (PRE), natural colour = NASA SVS LROC mosaic (visualization only),
// slope = derived from the DEM (EST), mean sunlight / Earth in view = PGDA maps (PRE).
// Tapping the terrain or typing a coordinate creates a point (3 decimals). Spec: designer/B-explore.designer.mds.
// Source of truth: this .tsx file (Preact). explore.js is generated by `npm --prefix web run build:ts`.
// The side panels are Preact templates rendered once into detached nodes (build/one) and swapped in with
// replaceChildren; the canvas overlay, the pin and the horizon SVG stay imperative (drawn from live geometry).
import { h, Fragment, render } from "../../vendor/preact/preact.module.js";
import type { ComponentChild } from "../../vendor/preact/preact.module.js";
import { mountShell } from "../core/shell.js";
import { mountTerrain } from "../core/terrain.js";
import { loadSites, windowMetrics, sealFor, apiOnline, loadRegion, sourced, api } from "../core/data.js";
import type { Site, SitesDoc, SiteSeriesLike } from "../core/data.js";
import { createLayerCard, sealEl } from "../core/layers.js";
import { t, fmtNum, lang } from "../core/i18n.js";
import { getState, setState, onState, hrefTo } from "../core/state.js";
import type { Layer } from "../core/state.js";
import { createMediaLoader } from "../core/media-client.js";
import { coordText, parseCoord, pgdaAt, rampColor, rampCss, horizonPoints, elRange, fmtVal } from "./mission-calc.js";
import type { RampName, HorizonPoint } from "./mission-calc.js";
// @ts-ignore TS7016
import { southStereoInverse, southStereoForward } from "../../lab/coords.js";
import "./mission-i18n.js";

interface ExSite extends Site { name: string; lat: number; lon: number; stereo_x_m: number; stereo_y_m: number; site_height_m: number | null }
interface Doc extends Omit<SitesDoc, "sites"> { sites: ExSite[] }
interface Geo { sunAz: number; sunEl: number; sunMargin: number; earthAz: number; earthEl: number; earthMargin: number }
interface Series extends SiteSeriesLike {
  at(t0: number): Geo | null;
  horizon: HorizonPoint[] | null;
  meta: SiteSeriesLike["meta"] & { provenance?: { terrain?: string; ray_parameters?: unknown } };
}
type Metrics = Omit<Awaited<ReturnType<typeof windowMetrics>>, "series"> & { series: Series };
/** web/lab/terrain.js TerrainGrid, as far as this screen reads it (untyped JS module). */
interface Grid {
  h: { source: string; method: string; native_resolution_m: number; layers: Record<string, { file: string; product: string; resolution_m: number }> };
  nx: number; ny: number; dx: number; x0: number; y0: number; min: number; max: number; data: ArrayLike<number>;
  contains(x: number, y: number): boolean; height(x: number, y: number): number | null; normal(x: number, y: number): { slopeDeg: number };
  slopeField(): ArrayLike<number>;
}
interface MapPoint { x: number; y: number; lat: number; lon: number; outside?: boolean }
interface Natural { w: number; h: number; d: Uint8ClampedArray }
interface MediaItem { title: string; page_url: string; credit: string; illustrative_only?: boolean }
type RangeMap = Record<string, [number, number]>;
type SealRow = [string, string, string | undefined];

const DAY = 24, $ = (id: string) => document.getElementById(id) as HTMLElement;

/** Renders a template into detached DOM nodes. Preact is only a template engine here: nothing re-renders them. */
function build(v: ComponentChild): ChildNode[] {
  const c = document.createElement("div"); render(v, c); return [...c.childNodes];
}
const one = (v: ComponentChild): HTMLElement => build(v)[0] as HTMLElement;
/**
 * Embeds a DOM node built by the core (seals, layer cards). The <mp-node> placeholder is swapped for the node
 * itself as soon as it is mounted, so the final DOM has no wrapper (child selectors in the CSS keep matching).
 */
function Node({ node }: { node: Node | null }) {
  return h("mp-node" as "span", { ref: (host: HTMLElement | null) => { if (host && node) host.replaceWith(node); } });
}
const el = (tag: string, cls?: string | null, text?: string | null): HTMLElement => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
const nd = (): string => t("nd");
const loadMedia = createMediaLoader(api);
interface LayerDef { id: string; key: string; unit: string; ramp: RampName | null; legend: string; status: string | null }
export const LAYERS: LayerDef[] = [
  { id: "altitude", key: "ex.l.altitude", unit: "ex.u.m", ramp: "altitude", legend: "ex.leg.altitude", status: null },
  { id: "natural", key: "ex.l.natural", unit: "ex.u.vis", ramp: null, legend: "ex.leg.natural", status: "VISUALIZATION" },
  { id: "slope", key: "ex.l.slope", unit: "ex.u.deg", ramp: "slope", legend: "ex.leg.slope", status: "ESTIMATE" },
  { id: "sun", key: "ex.l.sun", unit: "ex.u.pct", ramp: "sun", legend: "ex.leg.sun", status: null },
  { id: "earth", key: "ex.l.earth", unit: "ex.u.pct", ramp: "earth", legend: "ex.leg.earth", status: null },
];

let point: MapPoint | null = null;
const shell = mountShell({ screen: "explore", context: null, onLang: () => draw() });
const doc = (await loadSites()) as unknown as Doc;
if (!doc.sites.some(s => s.id === getState().site)) setState({ site: doc.sites[0].id });
const hours = (): number => getState().hours || 14 * DAY;
const online = await apiOnline();
const grid = (await loadRegion()) as Grid;
const terrain = await mountTerrain($("terrain"), { sites: doc.sites, selected: getState().site, onSelect: (id: string) => { point = null; setState({ site: id }); } });
const fetchU8 = (f: string): Promise<Uint8Array | null> => fetch(new URL("../../data/region/" + f, import.meta.url)).then(r => r.ok ? r.arrayBuffer() : null).then(b => b && new Uint8Array(b)).catch(() => null);
const [pSun, pEarth] = await Promise.all([fetchU8(grid.h.layers.pgda_sun.file), fetchU8(grid.h.layers.pgda_earth.file)]);
const slope = grid.slopeField();
let layer = new URLSearchParams(location.search).get("paint") || "altitude", tab = "layers", natural: Natural | false | null = null;

// ---- layer painting: one image per layer at grid resolution, drawn with the same transform as core/terrain.js
const overlay = el("canvas", "ex-overlay") as HTMLCanvasElement; overlay.setAttribute("aria-hidden", "true");
const tc = $("terrain"); tc.insertBefore(overlay, tc.children[1]);
const pin = el("div", "ex-pin"); pin.hidden = true; tc.append(pin);
const cache = new Map<string, HTMLCanvasElement>();
function finiteRange(arr: ArrayLike<number>): [number, number] { let lo = Infinity, hi = -Infinity; for (const v of Array.from(arr)) if (Number.isFinite(v)) { if (v < lo) lo = v; if (v > hi) hi = v; } return [lo, hi]; }
const RANGES: RangeMap = { altitude: [grid.min, grid.max], slope: [0, finiteRange(slope)[1]], sun: [0, 100], earth: [0, 100] };
async function loadNatural(): Promise<Natural | false> {
  if (natural !== null) return natural;
  try { const img = new Image(); img.src = new URL("../../data/moon/lroc_color_2k.jpg", import.meta.url).href; await img.decode();
    const c = document.createElement("canvas"); c.width = img.width; c.height = img.height; const g = c.getContext("2d") as CanvasRenderingContext2D; g.drawImage(img, 0, 0);
    natural = { w: img.width, h: img.height, d: g.getImageData(0, 0, img.width, img.height).data }; } catch { natural = false; }
  return natural;
}
async function layerImage(id: string): Promise<HTMLCanvasElement> {
  if (cache.has(id)) return cache.get(id) as HTMLCanvasElement;
  const { nx, ny } = grid, img = new ImageData(nx, ny), d = img.data;
  const nat = id === "natural" ? await loadNatural() : null;
  for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
    const k = j * nx + i, p = ((ny - 1 - j) * nx + i) * 4; let c: number[] | null = null;
    if (id === "altitude") { const v = grid.data[k]; if (Number.isFinite(v)) c = rampColor("altitude", (v - RANGES.altitude[0]) / (RANGES.altitude[1] - RANGES.altitude[0])); }
    else if (id === "slope") { const v = slope[k]; if (Number.isFinite(v)) c = rampColor("slope", v / RANGES.slope[1]); }
    else if (id === "sun" || id === "earth") { const a = id === "sun" ? pSun : pEarth; const v = a?.[k]; if (v != null && v <= 100) c = rampColor(id, v / 100); }
    else if (nat) { const { lat, lon } = southStereoInverse(grid.x0 + i * grid.dx, grid.y0 + j * grid.dx);
      const u = Math.floor(((lon + 180) / 360) * nat.w) % nat.w, v = Math.min(nat.h - 1, Math.floor(((90 - lat) / 180) * nat.h)), q = (v * nat.w + u) * 4; c = [nat.d[q], nat.d[q + 1], nat.d[q + 2]]; }
    if (c) { d[p] = c[0]; d[p + 1] = c[1]; d[p + 2] = c[2]; d[p + 3] = 255; }
  }
  const cv = document.createElement("canvas"); cv.width = nx; cv.height = ny; (cv.getContext("2d") as CanvasRenderingContext2D).putImageData(img, 0, 0);
  cache.set(id, cv); return cv;
}
async function paint() {
  const W = tc.clientWidth, H = tc.clientHeight, dpr = devicePixelRatio || 1;
  overlay.width = W * dpr; overlay.height = H * dpr;
  const g = overlay.getContext("2d") as CanvasRenderingContext2D; g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, W, H);
  // Same projection as the relief under it (core/terrain.js), so the layer lines up with the craters.
  if (!terrain.ready) { pin.hidden = true; return; } // map not framed yet (zero-size viewport): nothing to line up with
  const src = await layerImage(layer), mpp = terrain.mpp;
  const [x0, y0] = terrain.toPx(grid.x0, grid.y0 + (grid.ny - 1) * grid.dx), w = grid.nx * grid.dx / mpp, h = grid.ny * grid.dx / mpp;
  g.imageSmoothingEnabled = false; g.drawImage(src, x0, y0, w, h);
  // Soft edge where the data ends (the layer only covers its grid; no data is invented past it).
  g.globalCompositeOperation = "destination-out"; const f = Math.min(48, w / 6, h / 6);
  for (const [ax, ay, bx, by, rx, ry, rw, rh] of [[x0, 0, x0 + f, 0, x0, y0, f, h], [x0 + w, 0, x0 + w - f, 0, x0 + w - f, y0, f, h], [0, y0, 0, y0 + f, x0, y0, w, f], [0, y0 + h, 0, y0 + h - f, x0, y0 + h - f, w, f]]) {
    const gr = g.createLinearGradient(ax, ay, bx, by); gr.addColorStop(0, "rgba(0,0,0,1)"); gr.addColorStop(1, "rgba(0,0,0,0)"); g.fillStyle = gr; g.fillRect(rx, ry, rw, rh); }
  g.globalCompositeOperation = "source-over";
  if (point) { const [px, py] = terrain.toPx(point.x, point.y); pin.hidden = false; pin.style.left = px + "px"; pin.style.top = py + "px"; } else pin.hidden = true;
}

// ---- free area framing: chosen site/point between the side panels
function frame() {
  const s = site(), tx = point ? point.x : s.stereo_x_m, ty = point ? point.y : s.stereo_y_m;
  if (!point) terrain.select(s.id);
  terrain.view.cx = tx; terrain.view.cy = ty; // core/terrain.js centres it in the free area between the panels
  terrain.redraw(); paint();
}
const site = (): ExSite => doc.sites.find(s => s.id === getState().site) as ExSite;

overlay.addEventListener("click", e => {
  const r = tc.getBoundingClientRect(), [x, y] = terrain.fromPx(e.clientX - r.left, e.clientY - r.top);
  if (!grid.contains(x, y)) return; const { lat, lon } = southStereoInverse(x, y); point = { x, y, lat, lon }; draw();
});

function pointAt(lat: number, lon: number) { const [x, y] = southStereoForward(lat, lon); point = grid.contains(x, y) ? { x, y, lat, lon } : { x, y, lat, lon, outside: true }; }

async function draw() {
  const st = getState(), s = site();
  const m = (await windowMetrics(doc, s, st.start, hours())) as unknown as Metrics;
  const fmtDate = (d: Date) => new Intl.DateTimeFormat(lang(), { dateStyle: "medium", timeStyle: "short", timeZone: "UTC" }).format(d) + " UTC";
  shell.setContext({ site: point ? t("ex.point") : `${s.n} · ${s.name}`, date: fmtDate(new Date(m.t0)), days: fmtNum(hours() / DAY), seal: sealFor(doc.status), online,
    action: { label: t("ex.addCompare"), href: hrefTo("compare.html") } });
  drawLeft(); drawRight(s, m); dock(s); chips(); frame();
}

function drawLeft() {
  const left = $("left");
  if (tab === "sites") {
    left.replaceChildren(...build(
      <>
        {tabs()}
        <div class="ex-list">{doc.sites.map(x => (
          <button class="ex-radio" type="button" aria-pressed={!point && x.id === getState().site} onClick={() => { point = null; setState({ site: x.id }); }}>
            <span class="ex-n">{String(x.n)}</span><span>{x.name}</span>
          </button>
        ))}</div>
      </>));
    return;
  }
  left.replaceChildren(...build(
    <>
      {tabs()}
      <p class="mp-label">{t("ex.hint")}</p>
      <div class="ex-list" role="radiogroup" aria-label={t("ex.layers")}>{LAYERS.map(L => (
        <button class="ex-radio" type="button" role="radio" aria-checked={L.id === layer} data-layer={L.id}
          onClick={() => { layer = L.id; draw(); }}
          onKeyDown={(e: KeyboardEvent) => { const i = LAYERS.indexOf(L); if (e.key === "ArrowDown" || e.key === "ArrowUp") { e.preventDefault(); layer = LAYERS[(i + (e.key === "ArrowDown" ? 1 : LAYERS.length - 1)) % LAYERS.length].id; draw().then(() => (left.querySelector(`[data-layer="${layer}"]`) as HTMLElement | null)?.focus()); } }}>
          <span class="ex-dot"></span><span>{t(L.key)}</span><i class="ex-swatch" style={{ background: L.ramp ? rampCss(L.ramp) : "#8a8d90" }}></i>
          {L.id === "slope" ? <Node node={sealEl(sealFor("ESTIMATE"))} /> : null}
        </button>
      ))}</div>
      <Node node={legend()} />
    </>));
}
function tabs(): ComponentChild {
  return (
    <div class="ex-tabs">{["layers", "sites"].map(k => (
      <button class="mp-pill" type="button" aria-pressed={tab === k} onClick={() => { tab = k; drawLeft(); }}>{t("ex." + k)}</button>
    ))}</div>
  );
}
export function legendModel(id: string, ranges: RangeMap) {
  const L = LAYERS.find(x => x.id === id) as LayerDef;
  const r = ranges[id] || null;
  return { L, min: r ? r[0] : null, max: r ? r[1] : null };
}
function legend(): HTMLElement {
  const { L, min, max } = legendModel(layer, RANGES);
  const status = L.status || doc.status;
  const d = L.id === "slope" ? 1 : 0;
  const src = L.id === "altitude" || L.id === "slope" ? `${grid.h.source} · ${grid.h.method}` : L.id === "natural" ? "NASA SVS 4720 · lroc_color_2k.jpg" : grid.h.layers["pgda_" + L.id].product + " · " + grid.h.layers["pgda_" + L.id].resolution_m + " m";
  return one(
    <div class="mp-card ex-legend">
      <div class="ex-legend-head"><b>{t(L.key)}</b><span class="mp-label">{t(L.unit)}</span><Node node={sealEl(sealFor(status))} /></div>
      {L.ramp ? <>
        <div class="ex-ramp" style={{ background: rampCss(L.ramp) }}></div>
        <div class="ex-scale mp-coord"><span>{fmtVal(min, fmtNum, nd(), d)}</span><span>{fmtVal(max, fmtNum, nd(), d)}</span></div>
      </> : null}
      <p class="mp-label">{t(L.legend)}</p>
      {/* The provenance stays one tap away (the design legend is a compact card). */}
      <details class="ex-srcbox"><summary class="mp-label">{t("proof.source")}</summary><p class="mp-label ex-src">{src}</p></details>
    </div>);
}

function drawRight(s: ExSite, m: Metrics) {
  const right = $("right"); right.replaceChildren(card(s, m), fromHere(s, m, DESK_HORIZON));
  const mobile = $("sheet-body"); mobile.replaceChildren(card(s, m, true), fromHere(s, m));
  if (!point) {
    // Each render owns its own slot, so late results cannot duplicate a card or
    // attach it to a different site/coordinate. Both responsive layouts use the same request.
    for (const target of [right, mobile]) {
      const slot = el("div"); target.append(slot);
      mediaCard(s).then(c => {
        if (!slot.isConnected || point || site()?.id !== s.id) return;
        if (c) slot.replaceWith(c); else slot.remove();
      });
    }
  }
}

function rows(list: SealRow[]): ComponentChild {
  return (
    <table class="ex-rows"><tbody>{list.map(([k, v, seal]) => (
      <tr><th>{k}</th><td>{v}{seal ? <>{" "}<Node node={sealEl(seal)} /></> : null}</td></tr>
    ))}</tbody></table>
  );
}
function card(s: ExSite, m: Metrics, mobile?: boolean): HTMLElement {
  const x = point ? { n: "+", name: t("ex.point"), lat: point.lat, lon: point.lon } : s;
  const X = point ? point.x : s.stereo_x_m, Y = point ? point.y : s.stereo_y_m;
  const ps = pgdaAt(grid, pSun, X, Y), pe = pgdaAt(grid, pEarth, X, Y);
  const height = point ? sourced(point.outside ? null : grid.height(X, Y), { unit: "m", status: doc.status }) : sourced(s.site_height_m, { unit: "m", status: doc.status });
  const sl = sourced(point?.outside ? null : grid.normal(X, Y).slopeDeg, { unit: "°", status: "ESTIMATE" });
  const v = (n: number | null | undefined, d = 0, u = "") => fmtVal(n, fmtNum, nd(), d, u);
  const triple: SealRow[] = [[t("ex.sunVis"), v(m.sunPct.value, 0, "%"), m.sunPct.seal], [t("ex.earthVis"), v(m.earthPct.value, 0, "%"), m.earthPct.seal], [t("ex.night"), v(m.longestDarkH.value, 0, " h"), m.longestDarkH.seal]];
  return one(
    <article class="mp-card ex-site" id={mobile ? "m-card-site" : "card-site"}>
      <div class="ex-site-head">
        <span class="ex-n is-sel">{String(x.n)}</span>
        <div><h3>{x.name}</h3><p class="mp-coord">{coordText(x.lat, x.lon, fmtNum, nd())}</p></div>
        {point ? <button class="mp-pill ex-close" type="button" aria-label={t("ex.close")} onClick={() => { point = null; draw(); }}>×</button> : null}
      </div>
      {/* AUD-03: a free point only has the PGDA long-term mean, not the selected mission window. */}
      <h4 class="mp-label">{t("ex.light") + " · "}<span class="ex-jade">{point ? t("ex.pgdaLong") : t("ctx.days", { n: fmtNum(hours() / DAY) })}</span></h4>
      {point
        ? rows([[t("ex.pgdaSun"), v(ps, 0, "%"), ps == null ? "N/D" : sealFor(doc.status)], [t("ex.pgdaEarth"), v(pe, 0, "%"), pe == null ? "N/D" : sealFor(doc.status)], [t("ex.night"), nd(), "N/D"]])
        : mobile ? <div class="ex-glass-row">{triple.map(([k, val, seal]) => <div class="glass-in"><b>{val}</b><span>{k}</span><Node node={sealEl(seal)} /></div>)}</div> : rows(triple)}
      {!mobile ? <>
        <h4 class="mp-label">{t("ex.terrain") + " · "}<span class="ex-jade">{"DEM " + fmtNum(grid.h.native_resolution_m) + " m/px → " + fmtNum(grid.dx) + " m"}</span></h4>
        {rows([[t("mc.altitude"), v(height.value, 0, " m"), height.seal], [t("mc.slope"), v(sl.value, 1, "°"), sl.seal]])}
      </> : null}
      {point?.outside ? <p class="mp-label">{t("ex.outside")}</p> : null}
    </article>);
}

const DESK_HORIZON: [number, number] = [310, 70]; // desktop card: the chart is a 310 x 88 strip (70 + 18 for the N/E/S/W labels)
function fromHere(s: ExSite, m: Metrics, size: [number, number] | [] = []): HTMLElement {
  void s;
  const g = point ? null : m.series.at(m.t0), hz = point ? null : m.series.horizon;
  const status = point ? null : doc.status;
  let answer: string, why: SVGSVGElement | null;
  if (!hz || !g) { answer = t("ex.from.nd"); why = null; }
  else {
    const fmtM = (n: number) => t(n >= 0 ? "ex.above" : "ex.below", { n: fmtVal(Math.abs(n), fmtNum, nd(), 1, "°") });
    answer = t("ex.from.ans", { s: fmtM(g.sunMargin), e: fmtM(g.earthMargin) });
    why = horizonSvg(hz, g, ...size);
  }
  const c = createLayerCard({ id: "card-horizon", title: t("ex.from"), status: status || "NO_DATA", answer, why: why || undefined,
    layer: getState().layer === "answer" ? "why" : getState().layer, onLayer: (l: Layer) => setState({ layer: l }),
    proof: point ? [[t("proof.source"), nd()]] : [[t("proof.definition"), t("proof.definition.sun")], [t("proof.source"), m.series.meta.provenance?.terrain || nd()],
      ["ray", JSON.stringify(m.series.meta.provenance?.ray_parameters || {})], [t("proof.status"), `${doc.status} · ${t("seal." + sealFor(doc.status))}`]] }).el as HTMLElement;
  // AUD-02: a free point has no hourly series; Compare/Land would silently use the previous site's. Disable them.
  const dis = point ? { "aria-disabled": true as const, title: t("ex.point.noseries") } : {};
  const acts = one(
    <div class="ex-actions">
      <a class={"mp-pill is-primary" + (point ? " is-disabled" : "")} href={point ? undefined : hrefTo("compare.html")} {...dis}>{t("ex.compare")}</a>
      <a class={"mp-pill is-sim" + (point ? " is-disabled" : "")} href={point ? undefined : hrefTo("landing.html")} {...dis}>{t("ex.land")}</a>
    </div>);
  c.append(acts);
  if (point) c.append(el("p", "mp-label", t("ex.point.noseries")));
  return c;
}
export function horizonSvg(hz: HorizonPoint[], g: Geo, W = 320, Hh = 110): SVGSVGElement {
  const r = elRange(hz, [g.sunEl, g.earthEl]) as [number, number];
  const NS = "http://www.w3.org/2000/svg", svg = document.createElementNS(NS, "svg");
  svg.setAttribute("viewBox", `0 0 ${W} ${Hh + 18}`); svg.setAttribute("class", "ex-horizon"); svg.setAttribute("role", "img");
  const mk = (tag: string, at: Record<string, string | number>) => { const e = document.createElementNS(NS, tag); for (const [k, v] of Object.entries(at)) e.setAttribute(k, String(v)); svg.append(e); return e; };
  const pts = horizonPoints(hz, W, Hh, r[0], r[1]);
  mk("polygon", { points: `0,${Hh} ${pts} ${W},${Hh}`, fill: "#3a4048" });
  const y = (e: number) => Hh - ((e - r[0]) / (r[1] - r[0])) * Hh;
  for (const [az, e, col] of [[g.sunAz, g.sunEl, "#FFD166"], [g.earthAz, g.earthEl, "#4C9BFF"]] as [number, number, string][]) mk("circle", { cx: (az / 360) * W, cy: Math.max(6, Math.min(Hh, y(e))), r: 7, fill: col });
  ["N", "E", "S", "W"].forEach((d, i) => { const tx = mk("text", { x: (i / 4) * W + 4, y: Hh + 14, fill: "#B7C0C9", "font-size": 11 }); tx.textContent = d; });
  svg.setAttribute("aria-label", `horizon ${fmtNum(r[0], 1)}°…${fmtNum(r[1], 1)}°`);
  return svg;
}

function dock(s: ExSite) {
  const d = $("dock"), i = doc.sites.indexOf(s), n = doc.sites.length;
  const btn = (txt: string, label: string, fn: () => void) => <button class="mp-pill ex-round" type="button" aria-label={label} onClick={fn}>{txt}</button>;
  const go = (id: string) => { point = null; setState({ site: id }); };
  // Coordinates pill: shows the selected site/point and is also the "type a coordinate" field (Enter creates the point).
  const px = point ? point : s;
  // Scale bar: a round length that fits ~70 px at the current zoom.
  const nice = (m: number) => { const p = 10 ** Math.floor(Math.log10(m)); return [1, 2, 5, 10].map(k => k * p).filter(v => v <= m).pop() as number; };
  const mpp = terrain.mpp, len = mpp ? nice(mpp * 70) : 0;
  d.replaceChildren(...build(
    <>
      <p class="mc-hint">{t("ex.tap")}</p>
      <div class="ex-dock-row">
        {len ? <span class="mp-pill ex-scalebar"><i style={{ width: Math.round(len / mpp) + "px" }}></i>{len >= 1000 ? `${fmtNum(len / 1000)} km` : `${fmtNum(len)} m`}</span> : null}
        {btn("‹", t("mc.prev"), () => go(doc.sites[(i + n - 1) % n].id))}
        {btn("›", t("mc.next"), () => go(doc.sites[(i + 1) % n].id))}
        <select class="mp-pill is-primary ex-sel" aria-label={t("ctx.site")} onChange={(e: Event) => go((e.currentTarget as HTMLSelectElement).value)}>
          {doc.sites.map(x => <option value={x.id} selected={x.id === s.id}>{`${t("ctx.site")} ${x.n} · ${x.name}`}</option>)}
        </select>
        {btn("−", t("mc.zout"), () => { terrain.zoom(0.7); frame(); })}
        {btn("+", t("mc.zin"), () => { terrain.zoom(1.4); frame(); })}
        <form class="ex-coord" onSubmit={(e: Event) => {
          e.preventDefault(); const inp = (e.currentTarget as HTMLFormElement).querySelector("input") as HTMLInputElement;
          const c = parseCoord(inp.value.replace(/;/g, " ").replace(/(\d),(\d)/g, "$1.$2")); if (!c) { inp.setCustomValidity(t("ex.coord.bad")); inp.reportValidity(); return; } inp.setCustomValidity(""); pointAt(c.lat, c.lon); draw(); }}>
          <label class="sr-only" for="coord">{t("ex.coord")}</label>
          <input class="mp-coord" id="coord" placeholder={t("ex.coord.ph")} title={t("ex.coord.ph")} value={coordText(px.lat, px.lon, fmtNum, nd())} enterkeyhint="go" autocomplete="off"
            onFocus={(e: Event) => (e.currentTarget as HTMLInputElement).select()} />
        </form>
      </div>
    </>));
}
function chips() {
  $("chips").replaceChildren(...build(
    <>{LAYERS.filter(x => x.id !== "slope").map(L => <button class="mp-pill" type="button" aria-pressed={L.id === layer} onClick={() => { layer = L.id; draw(); }}>{t(L.key)}</button>)}</>));
}
const handle = $("handle"), sheet = $("sheet");
handle.onpointerdown = e => { handle.setPointerCapture(e.pointerId); const y0 = e.clientY, h0 = sheet.offsetHeight;
  handle.onpointermove = ev => { sheet.style.height = Math.max(110, Math.min(innerHeight - 180, h0 + (y0 - ev.clientY))) + "px"; };
  handle.onpointerup = () => { handle.onpointermove = null; frame(); }; };
handle.onkeydown = e => { if (e.key === "ArrowUp" || e.key === "ArrowDown") { e.preventDefault(); sheet.style.height = Math.max(110, Math.min(innerHeight - 180, sheet.offsetHeight + (e.key === "ArrowUp" ? 60 : -60))) + "px"; frame(); } };
addEventListener("resize", () => frame());
onState(() => draw());
draw();

// Official LROC images related to the site (GET /api/sites/{id}/media, from the legacy onboard "Visual" tab).
// Links only: the API returns page links and credits, never image bytes (LROC website terms).
async function mediaCard(s: ExSite): Promise<HTMLElement | null> {
  const items = (await loadMedia(s.id)) as MediaItem[] | null;
  if (items === null) {
    const c = el("article", "mp-card ex-media"); c.append(el("h3", null, t("ex.media")));
    const pt = lang() === "pt-BR", retry = el("button", "mp-pill", pt ? "Tentar novamente" : "Retry links") as HTMLButtonElement; retry.type = "button";
    retry.onclick = () => draw(); c.append(el("p", "mp-label", pt ? "Links oficiais indisponíveis; os dados locais permanecem utilizáveis." : "Official source links unavailable; local data remain usable."), retry);
    return c;
  }
  if (!items.length) return null;
  return one(
    <article class="mp-card ex-media"><h3>{t("ex.media")}</h3>{items.slice(0, 4).map(it => (
      <p class="mp-label"><a class="ex-media-link" href={it.page_url} target="_blank" rel="noopener noreferrer">{it.title}</a><br />{`${it.credit}${it.illustrative_only ? " · " + t("ex.media.ill") : ""}`}</p>
    ))}</article>);
}
